import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

// Helper function to generate a timestamped session suffix
const generateTimestampSuffix = () => {
    const now = new Date();
    const datePart = now.getFullYear() + "-" + String(now.getMonth() + 1).padStart(2, '0') + "-" + String(now.getDate()).padStart(2, '0');
    const timePart = String(now.getHours()).padStart(2, '0') + "-" + String(now.getMinutes()).padStart(2, '0') + "-" + String(now.getSeconds()).padStart(2, '0');
    return `${datePart}_${timePart}`;
};

function SessionInitialization() {
    const navigate = useNavigate();

    // State variables for user inputs
    const [studyId, setStudyId] = useState(localStorage.getItem('studyId') || "");
    const [sessionName, setSessionName] = useState(localStorage.getItem('sessionName') || "");
    const [videoNameSuffix, setVideoNameSuffix] = useState(localStorage.getItem('videoNameSuffix') || "");
    const [smartphoneIp, setSmartphoneIp] = useState(localStorage.getItem('smartphoneIp') || "192.168.4.245");
    const [baseSavePath, setBaseSavePath] = useState(localStorage.getItem('baseSavePath') || "data");
    
    // The unique sessionId and full path are now derived
    const [sessionId, setSessionId] = useState("");
    const [location, setLocation] = useState("");

    // UI state
    const [message, setMessage] = useState("");
    const [isNavigating, setIsNavigating] = useState(false);
    
    // A separate state for the initial timestamp, which doesn't change after load
    const [timestampSuffix, setTimestampSuffix] = useState(generateTimestampSuffix());

    // State for configuration management
    const [configName, setConfigName] = useState("");

    // Use a useEffect hook to update the derived sessionId and save path
    useEffect(() => {
        // Construct the full sessionId
        if (sessionName) {
            setSessionId(`${sessionName}_${timestampSuffix}`);
        } else {
            // Fallback if no session name is provided
            setSessionId(timestampSuffix);
        }

        // Construct the full save path
        if (studyId && sessionId) {
            const pathSeparator = baseSavePath.endsWith('/') || baseSavePath.endsWith('\\') ? '' : '/';
            setLocation(`${baseSavePath}${pathSeparator}${studyId}/${sessionId}`);
        } else {
            setLocation(baseSavePath);
        }

        // Save values to localStorage for persistence of the *last used* session
        localStorage.setItem('studyId', studyId);
        localStorage.setItem('sessionName', sessionName);
        localStorage.setItem('videoNameSuffix', videoNameSuffix);
        localStorage.setItem('smartphoneIp', smartphoneIp);
        localStorage.setItem('baseSavePath', baseSavePath);
        localStorage.setItem('sessionId', sessionId); // Save the combined ID for the next page
    }, [studyId, sessionName, videoNameSuffix, smartphoneIp, baseSavePath, sessionId, timestampSuffix]);

    const handleGoToCalibration = () => {
        if (!studyId || !sessionName) {
            setMessage("Error: Please enter both a Study ID and a Session Name.");
            return;
        }
        
        setIsNavigating(true);
        setMessage("Details saved. Navigating to Calibration...");
        
        setTimeout(() => {
            navigate('/calibration');
        }, 1500);
    };

    const handleSaveConfiguration = () => {
        if (!configName) {
            setMessage("Error: Please enter a name for the configuration to save.");
            return;
        }

        const configuration = {
            studyId,
            sessionName,
            videoNameSuffix,
            smartphoneIp,
            baseSavePath,
        };
        localStorage.setItem(`config_${configName}`, JSON.stringify(configuration));
        setMessage(`Configuration "${configName}" saved successfully!`);
    };

    const handleLoadConfiguration = () => {
        if (!configName) {
            setMessage("Error: Please enter the name of the configuration to load.");
            return;
        }

        const savedConfig = localStorage.getItem(`config_${configName}`);
        if (savedConfig) {
            try {
                const configuration = JSON.parse(savedConfig);
                setStudyId(configuration.studyId || "");
                setSessionName(configuration.sessionName || "");
                setVideoNameSuffix(configuration.videoNameSuffix || "");
                setSmartphoneIp(configuration.smartphoneIp || "192.168.4.245");
                setBaseSavePath(configuration.baseSavePath || "data");
                setMessage(`Configuration "${configName}" loaded successfully!`);
            } catch (error) {
                setMessage("Error: Could not parse saved configuration. It might be corrupted.");
                console.error("Error parsing saved configuration:", error);
            }
        } else {
            setMessage(`Error: Configuration "${configName}" not found.`);
        }
    };

    const handleBrowseFolder = () => {
        // In a real desktop application, this would open a folder dialog.
        // For a web application, we can only provide a message.
        setMessage("Direct folder browsing is not supported by web browsers due to security policies. Please manually type the desired path.");
    };

    return (
        <div className="container mx-auto p-4 max-w-2xl font-inter">
            <h2 className="text-3xl font-bold mb-4 text-gray-800">Session Initialization</h2>
            <p className="mb-6 text-gray-600">Enter the details to start a new recording session on the smartphone.</p>

            {/* Manage Configurations Section */}
            <div className="bg-gray-50 p-6 rounded-lg shadow-md mb-8">
                <h3 className="text-xl font-semibold mb-4 text-gray-700">Manage Configurations</h3>
                <div className="mb-4">
                    <label htmlFor="config-name" className="block text-gray-700 text-sm font-bold mb-2">
                        Configuration Name:
                    </label>
                    <input
                        type="text"
                        id="config-name"
                        value={configName}
                        onChange={(e) => setConfigName(e.target.value)}
                        className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline mb-4"
                        placeholder="e.g., default_settings"
                    />
                </div>
                <div className="flex flex-col sm:flex-row gap-4">
                    <button
                        onClick={handleSaveConfiguration}
                        disabled={!configName}
                        className="bg-green-500 hover:bg-green-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline disabled:opacity-50 disabled:cursor-not-allowed w-full sm:w-1/2"
                    >
                        Save Configuration
                    </button>
                    <button
                        onClick={handleLoadConfiguration}
                        disabled={!configName}
                        className="bg-blue-500 hover:bg-blue-700 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline disabled:opacity-50 disabled:cursor-not-allowed w-full sm:w-1/2"
                    >
                        Load Configuration
                    </button>
                </div>
            </div>

            {/* Session Details Section */}
            <div className="bg-white p-6 rounded-lg shadow-md mb-8">
                <h3 className="text-xl font-semibold mb-4 text-gray-700">Session Details</h3>
                <div className="grid grid-cols-1 gap-4"> {/* Changed to 1 column for base path */}
                    <div className="mb-4">
                        <label htmlFor="base-save-path" className="block text-gray-700 text-sm font-bold mb-2">
                            Base Save Path:
                        </label>
                        <div className="flex gap-2">
                            <input
                                type="text"
                                id="base-save-path"
                                value={baseSavePath}
                                onChange={(e) => setBaseSavePath(e.target.value)}
                                className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                                placeholder="e.g., C:\videos"
                            />
                            <button
                                onClick={handleBrowseFolder}
                                className="bg-gray-400 hover:bg-gray-600 text-white font-bold py-2 px-4 rounded focus:outline-none focus:shadow-outline flex-shrink-0"
                            >
                                Browse Folder
                            </button>
                        </div>
                    </div>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4"> {/* Remaining fields in 2 columns */}
                    <div className="mb-4 md:mb-0">
                        <label htmlFor="study-id" className="block text-gray-700 text-sm font-bold mb-2">
                            Study ID:
                        </label>
                        <input
                            type="text"
                            id="study-id"
                            value={studyId}
                            onChange={(e) => setStudyId(e.target.value)}
                            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                            placeholder="e.g., Study_ABC"
                        />
                    </div>
                    <div className="mb-4 md:mb-0">
                        <label htmlFor="session-name" className="block text-gray-700 text-sm font-bold mb-2">
                            Session Name:
                        </label>
                        <input
                            type="text"
                            id="session-name"
                            value={sessionName}
                            onChange={(e) => setSessionName(e.target.value)}
                            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                            placeholder="e.g., session_1"
                        />
                    </div>
                    <div className="mb-4 md:mb-0">
                        <label htmlFor="video-name-suffix" className="block text-gray-700 text-sm font-bold mb-2">
                            Video Name Suffix:
                        </label>
                        <input
                            type="text"
                            id="video-name-suffix"
                            value={videoNameSuffix}
                            onChange={(e) => setVideoNameSuffix(e.target.value)}
                            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                            placeholder="e.g., baseline_trial"
                        />
                    </div>
                    <div className="mb-4 md:mb-0">
                        <label htmlFor="smartphone-ip" className="block text-gray-700 text-sm font-bold mb-2">
                            Smartphone IP:
                        </label>
                        <input
                            type="text"
                            id="smartphone-ip"
                            value={smartphoneIp}
                            onChange={(e) => setSmartphoneIp(e.target.value)}
                            className="shadow appearance-none border rounded w-full py-2 px-3 text-gray-700 leading-tight focus:outline-none focus:shadow-outline"
                            placeholder="e.g., 192.168.1.100"
                        />
                    </div>
                </div>
            </div>

            {/* Next Step Section */}
            <div className="bg-gray-50 p-6 rounded-lg shadow-md mb-8">
                <h3 className="text-xl font-semibold mb-4 text-gray-700">Next Step</h3>
                <div className="border border-gray-300 p-4 rounded-md mb-6">
                    <p className="text-gray-700 mb-2">
                        <strong className="font-semibold">Derived Session ID:</strong>{" "}
                        <code className="bg-gray-200 px-2 py-1 rounded-sm text-sm">{sessionId || "Not set"}</code>
                    </p>
                    <p className="text-gray-700">
                        <strong className="font-semibold">Full Save Path:</strong>{" "}
                        <code className="bg-gray-200 px-2 py-1 rounded-sm text-sm">{location || "Not set"}</code>
                    </p>
                </div>
                <button
                    onClick={handleGoToCalibration}
                    disabled={isNavigating || !studyId || !sessionName}
                    className="bg-purple-600 hover:bg-purple-800 text-white font-bold py-3 px-6 rounded-lg shadow-lg focus:outline-none focus:shadow-outline transition duration-300 ease-in-out transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed w-full"
                >
                    {isNavigating ? "Saving..." : "Go to Calibration"}
                </button>
                {message && (
                    <p className={`mt-4 text-center font-semibold ${isNavigating ? 'text-orange-500' : 'text-red-600'}`}>
                        {message}
                    </p>
                )}
            </div>
        </div>
    );
}

export default SessionInitialization;
